#include "fragment/json.hpp"
#include <sstream>
namespace frag{static std::string q(const std::string&s){std::string o="\"";for(char c:s){if(c=='"'||c=='\\'){o+='\\';o+=c;}else o+=c;}return o+"\"";}std::string json(const Result&r){std::ostringstream o;o<<"{\"status\":"<<q(r.status)<<",\"source_size\":"<<r.source_size<<",\"block_size\":"<<r.block_size<<",\"fragments\":[";for(size_t i=0;i<r.fragments.size();i++){auto&f=r.fragments[i];if(i)o<<",";o<<"{\"id\":"<<f.id<<",\"physical\":"<<f.physical<<",\"length\":"<<f.length<<",\"type\":"<<q(name(f.type))<<",\"anchor_score\":"<<f.anchor_score<<"}";}o<<"],\"edges\":[";for(size_t i=0;i<r.edges.size();i++){auto&e=r.edges[i];if(i)o<<",";o<<"{\"from\":"<<e.from<<",\"to\":"<<e.to<<",\"score\":"<<e.score<<"}";}o<<"],\"chains\":[";for(size_t i=0;i<r.chains.size();i++){auto&c=r.chains[i];if(i)o<<",";o<<"{\"id\":"<<c.id<<",\"type\":"<<q(name(c.type))<<",\"score\":"<<c.score<<",\"total_size\":"<<c.total_size<<",\"fragments\":[";for(size_t j=0;j<c.fragments.size();j++){if(j)o<<",";o<<c.fragments[j];}o<<"]}";}o<<"]}";return o.str();}}
